// Runnable demo: retention (delete by age) vs compaction (latest per key).
package com.bank.cleanup.demo;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class CleanupDemo {
    private static final Logger log = Logger.getLogger(CleanupDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        long now = 1000; // logical time units

        // EVENT FEED topic: cleanup.policy=delete, retention window = 5 units
        RetentionLog eventFeed = new RetentionLog("transactions", 5);
        eventFeed.append(new Record("SAV2001", "DEBIT 50000", now - 10)); // old
        eventFeed.append(new Record("SAV2001", "CREDIT 8000", now - 2));  // recent
        eventFeed.append(new Record("CUR3001", "DEBIT 1500", now - 1));   // recent
        eventFeed.runRetention(now);

        // BALANCE topic: cleanup.policy=compact, keep latest value per key
        CompactedLog balances = new CompactedLog("account-balances");
        balances.append(new Record("SAV2001", "balance=1000000", now - 9));
        balances.append(new Record("SAV2001", "balance=950000", now - 6));
        balances.append(new Record("SAV2001", "balance=958000", now - 1)); // latest for SAV2001
        balances.append(new Record("CUR3001", "balance=250000", now - 5));
        balances.append(new Record("CUR3001", null, now));                  // tombstone: closed
        balances.runCompaction();
    }
}

