class Record {
    private final String key;
    private final String value; // null value = tombstone (delete marker)
    private final long timestamp;
    Record(String key, String value, long timestamp) {
        this.key = key; this.value = value; this.timestamp = timestamp;
    }
    String getKey() { return key; }
    String getValue() { return value; }
    long getTimestamp() { return timestamp; }
    boolean isTombstone() { return value == null; }
    @Override public String toString() {
        return key + "=" + (value == null ? "<tombstone>" : value) + " @t" + timestamp;
    }
}

