class RetentionLog {
    private static final Logger log = Logger.getLogger(RetentionLog.class.getName());
    private final String topic;
    private final long retentionWindow;
    private final List<Record> records = new ArrayList<>();
    RetentionLog(String topic, long retentionWindow) {
        this.topic = topic; this.retentionWindow = retentionWindow;
    }
    void append(Record r) { records.add(r); }
    // Retention: drop records older than (now - window), ignoring keys
    void runRetention(long now) {
        long cutoff = now - retentionWindow;
        List<Record> kept = new ArrayList<>();
        for (Record r : records) {
            if (r.getTimestamp() >= cutoff) kept.add(r);
            else log.info(() -> "[" + topic + "] RETENTION deleted (too old) " + r);
        }
        records.clear(); records.addAll(kept);
        log.info(() -> "[" + topic + "] after retention keeps: " + records);
    }
}

