class CompactedLog {
    private static final Logger log = Logger.getLogger(CompactedLog.class.getName());
    private final String topic;
    private final List<Record> records = new ArrayList<>();
    CompactedLog(String topic) { this.topic = topic; }
    void append(Record r) { records.add(r); }
    // Compaction: keep only the LATEST record per key; tombstone removes the key
    void runCompaction() {
        Map<String, Record> latestByKey = new LinkedHashMap<>();
        for (Record r : records) latestByKey.put(r.getKey(), r); // later overwrites earlier
        List<Record> compacted = new ArrayList<>();
        for (Record r : latestByKey.values()) {
            if (r.isTombstone()) {
                log.info(() -> "[" + topic + "] COMPACTION key " + r.getKey()
                        + " deleted via tombstone");
            } else {
                compacted.add(r);
            }
        }
        log.info(() -> "[" + topic + "] after compaction keeps latest-per-key: " + compacted);
    }
}

